+import sales from './sales.json' with {type:'json'};
+
+const ISO_DATE_RE = /^\d{4}-\d{2}-\d{2}$/;
+const ALLOWED_FIELDS = ['start_date', 'end_date'];
+
+function isValidDate(s) {
+  if (typeof s !== 'string' || !ISO_DATE_RE.test(s)) return false;
+  const [y, m, d] = s.split('-').map(Number);
+  const dt = new Date(Date.UTC(y, m - 1, d));
+  return (
+    dt.getUTCFullYear() === y &&
+    dt.getUTCMonth() === m - 1 &&
+    dt.getUTCDate() === d
+  );
+}
+
+export async function listTools() {
+  return [
+    {
+      name: 'sales_report',
+      description: 'Sum sales rows within an inclusive date range.',
+      inputSchema: {
+        type: 'object',
+        properties: {
+          start_date: { type: 'string', description: 'ISO date (YYYY-MM-DD)' },
+          end_date: { type: 'string', description: 'ISO date (YYYY-MM-DD)' }
+        },
+        required: ['start_date', 'end_date'],
+        additionalProperties: false
+      }
+    }
+  ];
+}
+
+export async function callTool(name, args = {}) {
+  if (name !== 'sales_report') {
+    throw new Error(`Unknown tool: ${name}`);
+  }
+  for (const key of Object.keys(args)) {
+    if (!ALLOWED_FIELDS.includes(key)) {
+      throw new Error(`Unknown field: ${key}`);
+    }
+  }
+  const { start_date, end_date } = args;
+  if (!isValidDate(start_date)) {
+    throw new Error('Invalid start_date');
+  }
+  if (!isValidDate(end_date)) {
+    throw new Error('Invalid end_date');
+  }
+  if (start_date > end_date) {
+    throw new Error('start_date must not be after end_date');
+  }
+  let total = 0;
+  let count = 0;
+  for (const row of sales) {
+    if (row.date >= start_date && row.date <= end_date) {
+      total += row.amount;
+      count += 1;
+    }
+  }
+  return {
+    content: [{ type: 'text', text: `total: ${total}, rows: ${count}` }]
+  };
+}
